import * as d3 from 'd3';
import {
  Sel, drawLabel, drawArrow, drawStepBox, drawTensorGrid,
  drawTensor, drawMatrixBlock, fmtNum,
} from '../primitives';
import { ComputationGraph } from '../../graph/types';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

interface AttnStep {
  id: number;
  label: string;
  shortLabel: string;
  formula: string;
  explanation: string;
  code: { title: string; lines: string[] };
  svgGroup: string;
  color: string;
  fill: string;
}

function lbl(g: Sel, x: number, y: number, text: string, opts: { size?: number; weight?: string; color?: string; font?: string; anchor?: 'start' | 'middle' | 'end' } = {}): void {
  drawLabel(g, x, y, text, opts);
}

function arrowDown(g: Sel, x: number, y1: number, y2: number, color = '#78909c'): void {
  drawArrow(g, x, y1, x, y2, { color });
}

function arrowH(g: Sel, x1: number, x2: number, y: number, color = '#78909c'): void {
  drawArrow(g, x1, y, x2, y, { color });
}

function drawHeader(g: Sel, cx: number, y: number, title: string, subtitle: string): number {
  lbl(g, cx, y, title, { size: 16, weight: '700' });
  y += 22;
  lbl(g, cx, y, subtitle, { size: 10, color: '#888' });
  return y + 40;
}

function drawSmallMatrix(g: Gsel, x: number, y: number, rows: number, cols: number, cellSize: number, label: string, color: string): void {
  const group = g.append('g');
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      group.append('rect')
        .attr('x', x + c * cellSize)
        .attr('y', y + r * cellSize)
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', d3.interpolate(color, '#ffffff')(0.15 + Math.random() * 0.25))
        .attr('stroke', '#e0e0e0')
        .attr('stroke-width', 0.3);
    }
  }
  lbl(group as Sel, x + (cols * cellSize) / 2, y + rows * cellSize + 12, label, { size: 8, color: '#666' });
}

function drawAttentionHeatmap(
  g: Gsel, x: number, y: number, seqLen: number,
  maskType: 'causal' | 'none' | 'sliding' | 'sparse',
  windowSize?: number,
): number {
  const displaySize = Math.min(seqLen, 12);
  const cellSize = Math.min(14, 160 / displaySize);
  const gridW = displaySize * cellSize;
  const group = g.append('g');

  for (let r = 0; r < displaySize; r++) {
    for (let c = 0; c < displaySize; c++) {
      let isMasked = false;
      if (maskType === 'causal') isMasked = c > r;
      else if (maskType === 'sliding' && windowSize) isMasked = Math.abs(c - r) > windowSize;
      else if (maskType === 'sparse') {
        const isLocal = Math.abs(c - r) <= 2;
        const isGlobal = c < 2 || r < 2;
        const isRandom = ((c * 7 + r * 13) % 5) === 0;
        isMasked = !(isLocal || isGlobal || isRandom);
      }
      const val = isMasked ? 0 : Math.random() * 0.6 + 0.1;
      group.append('rect')
        .attr('x', x + c * cellSize)
        .attr('y', y + r * cellSize)
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', isMasked ? '#f5f5f5' : d3.interpolateOranges(val))
        .attr('stroke', '#e0e0e0')
        .attr('stroke-width', 0.3);
    }
  }

  // Add labels around axes
  if (maskType === 'causal') {
    lbl(group as Sel, x - 10, y + gridW / 2, 'query i', { size: 8, color: '#666', anchor: 'end' });
    lbl(group as Sel, x + gridW / 2, y - 8, 'key j', { size: 8, color: '#666' });
    // diagonal line
    group.append('line')
      .attr('x1', x).attr('y1', y)
      .attr('x2', x + gridW).attr('y2', y + gridW)
      .attr('stroke', '#ef4444').attr('stroke-width', 1).attr('stroke-dasharray', '3,3');
    lbl(group as Sel, x + gridW + 8, y + gridW / 2 - 10, 'future', { size: 7, color: '#ef4444' });
    lbl(group as Sel, x + gridW / 2 - 15, y + gridW + 22, 'causal mask', { size: 8, color: '#ef4444' });
  } else {
    lbl(group as Sel, x + gridW / 2, y + gridW + 14, `Attention scores (${maskType})`, { size: 9, color: '#666' });
  }

  return gridW + 40;
}

function drawMaskPattern(
  g: Gsel, x: number, y: number, seqLen: number,
  pattern: 'causal' | 'sliding' | 'sparse' | 'none',
  windowSize?: number,
): number {
  const displaySize = Math.min(seqLen, 14);
  const cellSize = Math.min(10, 140 / displaySize);
  const gridW = displaySize * cellSize;
  const group = g.append('g');

  for (let r = 0; r < displaySize; r++) {
    for (let c = 0; c < displaySize; c++) {
      let allowed = true;
      if (pattern === 'causal') allowed = c <= r;
      else if (pattern === 'sliding' && windowSize) allowed = Math.abs(c - r) <= windowSize;
      else if (pattern === 'sparse') {
        const isLocal = Math.abs(c - r) <= 2;
        const isGlobal = c < 2 || r < 2;
        const isRandom = ((c * 7 + r * 13) % 5) === 0;
        allowed = isLocal || isGlobal || isRandom;
      }
      group.append('rect')
        .attr('x', x + c * cellSize)
        .attr('y', y + r * cellSize)
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', allowed ? '#22c55e' : '#fee2e2')
        .attr('stroke', '#e0e0e0')
        .attr('stroke-width', 0.3);
    }
  }

  const labelMap: Record<string, string> = {
    causal: 'Causal mask: white = blocked',
    sliding: `Sliding window: w=${windowSize}`,
    sparse: 'Sparse: local + global + random',
    none: 'No mask: all allowed',
  };
  lbl(group as Sel, x + gridW / 2, y + gridW + 14, labelMap[pattern], { size: 8, color: '#666' });
  return gridW + 30;
}

function drawHeadSplit(g: Gsel, cx: number, y: number, nHeads: number, dHead: number): number {
  const displayHeads = Math.min(nHeads, 6);
  const headW = 40;
  const headH = 50;
  const gap = 12;
  const totalW = displayHeads * headW + (displayHeads - 1) * gap;
  const startX = cx - totalW / 2;

  for (let h = 0; h < displayHeads; h++) {
    const hx = startX + h * (headW + gap);
    const headGroup = g.append('g');
    drawSmallMatrix(headGroup, hx, y, 5, 3, headW / 3, `h${h}`, '#dbeafe');
    // label d_head inside
    lbl(headGroup as Sel, hx + headW / 2, y + headH / 2, `d=${dHead}`, { size: 6, color: '#2563eb' });
  }

  if (nHeads > displayHeads) {
    lbl(g as Sel, cx + totalW / 2 + 20, y + headH / 2, `...${nHeads - displayHeads} more`, { size: 8, color: '#888' });
  }

  lbl(g as Sel, cx, y + headH + 18, `Reshape: [batch, seq, d_model] → [batch, ${nHeads}, seq, ${dHead}]`, { size: 9, color: '#666' });
  return headH + 40;
}

// ── Standard MHA ──────────────────────────────────────────────────────────────

function renderStandard(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'Multi-Head Attention (Standard)', `d_model=${dModel}  n_heads=${nHeads}  seq_len=${seqLen}  d_head=${dHead}`);

  // Input
  const sIn = g.append('g').attr('class', 'step-node');
  drawTensor(sIn as Sel, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  // Three projection matrices side by side
  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  // Arrows from input to matrices
  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  // Output tensors
  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V`, '#dbeafe', '#2563eb');
  y += 110;

  // Step 2: Split heads
  const s2 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 150, y, 300, 42, 'Step 2 — Split into Heads', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `[batch, n_heads, seq, d_head]` });
  y += 58;

  y += drawHeadSplit(s2, cx, y, nHeads, dHead);

  // Step 3: Compute attention scores
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Attention Scores QK^T / √d_head', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'scores = Q @ K^T / √d_head' });
  y += 58;

  // QK^T matrix multiplication illustration
  drawSmallMatrix(s3, cx - 130, y, 5, 5, 12, 'Q [seq, d]', '#dbeafe');
  lbl(s3 as Sel, cx - 55, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, cx - 30, y, 5, 5, 12, 'K^T [d, seq]', '#dbeafe');
  arrowH(s3 as Sel, 35, 75, y + 30, '#9333ea');
  drawSmallMatrix(s3, cx + 80, y, 5, 5, 12, 'scores [seq, seq]', '#f3e8ff');
  lbl(s3 as Sel, cx + 80, y + 90, `÷ √${dHead}`, { size: 9, color: '#9333ea' });
  y += 110;

  // Step 4: Apply mask + softmax
  const s4 = g.append('g').attr('class', 'step-node step-attn-mask').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 150, y, 300, 42, 'Step 4 — Causal Mask + Softmax', { step: 4, fill: '#fef3c7', stroke: '#d97706', formula: 'A = softmax(mask(scores))' });
  y += 58;

  const heatH = drawAttentionHeatmap(s4, cx - 80, y, seqLen, 'causal');
  y += heatH + 10;

  // Step 5: Weighted sum with V
  const s5 = g.append('g').attr('class', 'step-node step-attn-weighted').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 160, y, 320, 42, 'Step 5 — Weighted Sum A · V', { step: 5, fill: '#f3e8ff', stroke: '#9333ea', formula: 'head_out = A @ V' });
  y += 58;

  drawSmallMatrix(s5, cx - 130, y, 5, 5, 12, 'A [seq, seq]', '#fef3c7');
  lbl(s5 as Sel, cx - 55, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s5, cx - 30, y, 5, 4, 12, 'V [seq, d]', '#dbeafe');
  arrowH(s5 as Sel, 30, 70, y + 24, '#9333ea');
  drawSmallMatrix(s5, cx + 80, y, 5, 4, 12, 'head_out', '#f3e8ff');
  y += 90;

  // Step 6: Concatenate and project
  const s6 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '6');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s6 as Sel, cx - 150, y, 300, 42, 'Step 6 — Concatenate Heads + Output Projection', { step: 6, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;

  // concat representation
  for (let h = 0; h < Math.min(nHeads, 4); h++) {
    drawSmallMatrix(s6, cx - 100 + h * 55, y, 5, 2, 10, `h${h}`, '#f3e8ff');
  }
  if (nHeads > 4) lbl(s6 as Sel, cx + 130, y + 25, `...${nHeads - 4}`, { size: 8, color: '#888' });

  arrowH(s6 as Sel, 160, 210, y + 25, '#ea580c');
  drawMatrixBlock(s6 as Sel, cx + 110, y, { width: 70, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  arrowH(s6 as Sel, 185, 270, y + 25, '#ea580c');
  drawTensor(s6 as Sel, cx + 140, y + 10, 100, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  // Params and FLOPs
  const totalParams = dModel * dModel * 4;
  lbl(g, cx, y, `Params: ${fmtNum(totalParams)}  (4 × ${fmtNum(dModel * dModel)})`, { size: 10, color: '#2563eb', weight: '600' });
  y += 18;
  lbl(g, cx, y, `FLOPs: O(batch · n_heads · seq² · d_head) attention + O(batch · seq · 4d_model²) projections`, { size: 10, color: 'var(--text-muted)' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Project to Q, K, V', shortLabel: 'Q/K/V Projection',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Three linear projections transform the input into query, key, and value matrices. Each has ${fmtNum(dModel * dModel)} parameters. Queries and keys compute attention scores; values carry information to aggregate.`,
      code: { title: 'Q/K/V Projection', lines: ['self.Wq = nn.Linear(d, d, bias=False)', 'self.Wk = nn.Linear(d, d, bias=False)', 'self.Wv = nn.Linear(d, d, bias=False)', '', 'q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Split into Heads', shortLabel: 'Head Split',
      formula: '[batch, seq, d_model] → [batch, n_heads, seq, d_head]',
      explanation: `d_model is reshaped into ${nHeads} heads of dimension ${dHead}. Each head operates independently, learning different attention patterns in parallel.`,
      code: { title: 'Head Split', lines: [`q = q.view(b, s, ${nHeads}, ${dHead}).transpose(1, 2)`, `k = k.view(b, s, ${nHeads}, ${dHead}).transpose(1, 2)`, `v = v.view(b, s, ${nHeads}, ${dHead}).transpose(1, 2)`] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Compute Attention Scores', shortLabel: 'QK^T',
      formula: 'scores = Q @ K^T / √d_head',
      explanation: `For each head, compute pairwise compatibility scores between all positions. The scale factor 1/√${dHead} prevents dot products from growing too large.`,
      code: { title: 'Scores', lines: [`scores = (q @ k.transpose(-2, -1)) / math.sqrt(${dHead})`] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Causal Mask + Softmax', shortLabel: 'Mask',
      formula: 'A = softmax(mask(scores))',
      explanation: 'Causal masking sets future positions to -∞, then softmax normalizes scores into a probability distribution over attended positions.',
      code: { title: 'Mask + Softmax', lines: ['scores = scores.masked_fill(mask == 0, float("-inf"))', 'attn = F.softmax(scores, dim=-1)'] },
      svgGroup: 'step-attn-mask', color: '#d97706', fill: '#fef3c7' },
    { id: 5, label: 'Weighted Sum with V', shortLabel: 'A @ V',
      formula: 'head_out = A @ V',
      explanation: 'Each position computes a weighted average of value vectors, where weights are the attention probabilities.',
      code: { title: 'Weighted Sum', lines: ['out = attn @ v  # [batch, n_heads, seq, d_head]'] },
      svgGroup: 'step-attn-weighted', color: '#9333ea', fill: '#f3e8ff' },
    { id: 6, label: 'Concatenate and Project', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Head outputs are concatenated back to d_model and projected through W_o. This combines information from all ${nHeads} heads into a single representation.`,
      code: { title: 'Output Projection', lines: ['out = out.transpose(1, 2).reshape(b, s, d)', 'return self.Wo(out)'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── GQA / MQA ─────────────────────────────────────────────────────────────────

function renderGQAMQA(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number, isMQA: boolean)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const nKVHeads = isMQA ? 1 : Math.max(1, Math.floor(nHeads / 4));
  const qPerKV = Math.floor(nHeads / nKVHeads);
  const variant = isMQA ? 'Multi-Query' : 'Grouped-Query';
  let y = 28;

  y = drawHeader(g, cx, y, `Attention — ${variant}`, `d_model=${dModel}  n_heads=${nHeads}  n_kv_heads=${nKVHeads}  d_head=${dHead}`);

  // Input
  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: Asymmetric QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Asymmetric Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: `Q: [d, d], K/V: [d, ${dHead}×${nKVHeads}]` });
  y += 58;

  // Wq full
  drawMatrixBlock(s1 as Sel, cx - 160, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  // Wk/Wv smaller
  drawMatrixBlock(s1 as Sel, cx - 30, y, { width: 55, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dHead * nKVHeads}]`, fill: '#dcfce7', stroke: '#16a34a' });
  drawMatrixBlock(s1 as Sel, cx + 45, y, { width: 55, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dHead * nKVHeads}]`, fill: '#dcfce7', stroke: '#16a34a' });

  arrowDown(s1 as Sel, cx - 120, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx - 2, y - 22, y - 2, '#16a34a');
  arrowDown(s1 as Sel, cx + 72, y - 22, y - 2, '#16a34a');

  drawTensor(s1 as Sel, cx - 160, y + 70, 80, 24, `Q`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 30, y + 70, 55, 24, `K`, '#dcfce7', '#16a34a');
  drawTensor(s1 as Sel, cx + 45, y + 70, 55, 24, `V`, '#dcfce7', '#16a34a');
  y += 110;

  // Step 2: Head split (Q many heads, KV few heads)
  const s2 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Split Heads (Q dense, KV shared)', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `Q: [${nHeads} heads], K/V: [${nKVHeads} heads]` });
  y += 58;

  // Q heads
  const qHeadsShown = Math.min(nHeads, 8);
  lbl(s2 as Sel, cx - 140, y, `Q heads (${nHeads})`, { size: 9, weight: '600', color: '#2563eb' });
  drawTensorGrid(s2 as Sel, cx - 180, y + 12, { rows: 2, cols: qHeadsShown, cellW: 14, cellH: 14, maxDisplayRows: 2, maxDisplayCols: 8, label: '', showEllipsis: nHeads > 8 });

  // KV heads
  const kvHeadsShown = Math.min(nKVHeads, 4);
  lbl(s2 as Sel, cx + 80, y, `K/V heads (${nKVHeads})`, { size: 9, weight: '600', color: '#16a34a' });
  drawTensorGrid(s2 as Sel, cx + 40, y + 12, { rows: 2, cols: kvHeadsShown, cellW: 14, cellH: 14, maxDisplayRows: 2, maxDisplayCols: 4, label: '', showEllipsis: nKVHeads > 4 });
  y += 70;

  // Step 3: Broadcast KV to Q
  const s3 = g.append('g').attr('class', 'step-node step-attn-broadcast').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Broadcast K/V to Q Heads', { step: 3, fill: '#ffedd5', stroke: '#ea580c', formula: `Each KV head → ${qPerKV} Q heads` });
  y += 58;

  // Broadcast arrows
  const kvXStart = cx - (nKVHeads * 60) / 2 + 30;
  const qXStart = cx - (nHeads * 30) / 2 + 15;
  for (let q = 0; q < Math.min(nHeads, 8); q++) {
    const kvIdx = Math.floor(q / qPerKV);
    const kx = kvXStart + kvIdx * 60;
    const qx = qXStart + q * 30;
    g.append('line')
      .attr('x1', kx).attr('y1', y)
      .attr('x2', qx).attr('y2', y + 40)
      .attr('stroke', '#ea580c').attr('stroke-width', 1).attr('opacity', 0.6);
  }
  lbl(s3 as Sel, cx, y + 55, `${nKVHeads} KV heads broadcast to ${nHeads} Q heads`, { size: 9, color: '#666' });
  y += 75;

  // Step 4: Attention
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 140, y, 280, 42, 'Step 4 — Standard Attention with Shared K/V', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'softmax(QK^T / √d) · V' });
  y += 58;

  drawAttentionHeatmap(s4, cx - 80, y, seqLen, 'causal');
  y += 190;

  // Step 5: Output projection
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 100, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  // Params
  const qParams = dModel * dModel;
  const kvParams = dModel * dHead * nKVHeads;
  const outParams = dModel * dModel;
  const totalParams = qParams + kvParams * 2 + outParams;
  lbl(g, cx, y, `Params: ${fmtNum(totalParams)}  (Q ${fmtNum(qParams)} + K/V ${fmtNum(kvParams * 2)} + Out ${fmtNum(outParams)})`, { size: 10, color: '#2563eb', weight: '600' });
  y += 18;
  lbl(g, cx, y, `KV cache reduction: ${nKVHeads}/${nHeads} of standard`, { size: 10, color: '#ea580c' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Asymmetric Q/K/V Projection', shortLabel: 'Asymmetric QKV',
      formula: `Q: [d, d], K/V: [d, ${dHead * nKVHeads}]`,
      explanation: `Q uses full ${nHeads} heads; K/V use only ${nKVHeads} head${nKVHeads > 1 ? 's' : ''}. This reduces KV cache memory.`,
      code: { title: 'Asymmetric Projection', lines: [`Wq: [${dModel}, ${dModel}]`, `Wk: [${dModel}, ${dHead * nKVHeads}]`, `Wv: [${dModel}, ${dHead * nKVHeads}]`] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Split Heads (Q dense, KV shared)', shortLabel: 'Head Split',
      formula: `Q: [${nHeads}], K/V: [${nKVHeads}]`,
      explanation: `Q is split into ${nHeads} heads; K/V into ${nKVHeads} heads.`,
      code: { title: 'Split', lines: [`q = q.view(..., ${nHeads}, ${dHead})`, `k = k.view(..., ${nKVHeads}, ${dHead})`, `v = v.view(..., ${nKVHeads}, ${dHead})`] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Broadcast K/V to Q Heads', shortLabel: 'KV Broadcast',
      formula: `K/V: [${nKVHeads}] → [${nHeads}]`,
      explanation: `Each K/V head is shared across ${qPerKV} Q heads. During attention, K/V are broadcast to match Q head count.`,
      code: { title: 'Broadcast', lines: ['k = k.repeat_interleave(q_per_kv, dim=1)', 'v = v.repeat_interleave(q_per_kv, dim=1)'] },
      svgGroup: 'step-attn-broadcast', color: '#ea580c', fill: '#ffedd5' },
    { id: 4, label: 'Attention', shortLabel: 'Attention',
      formula: 'softmax(QK^T / √d_head) · V',
      explanation: 'Standard scaled dot-product attention with broadcasted K/V.',
      code: { title: 'Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'attn = softmax(scores, dim=-1)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Concatenate head outputs and project.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Cross-Attention ───────────────────────────────────────────────────────────

function renderCrossAttention(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const kvSeqLen = seqLen * 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'Cross-Attention (Encoder→Decoder)', `d_model=${dModel}  n_heads=${nHeads}  q_seq=${seqLen}  kv_seq=${kvSeqLen}`);

  // Two inputs
  const sIn = g.append('g').attr('class', 'step-node');
  drawTensor(sIn as Sel, cx - 180, y, 140, 28, `decoder [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(sIn as Sel, cx + 40, y, 140, 28, `encoder [b, ${kvSeqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 50;

  // Step 1: Q from decoder, K/V from encoder
  const s1 = g.append('g').attr('class', 'step-node step-attn-cross').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 170, y, 340, 42, 'Step 1 — Q from Decoder, K/V from Encoder', { step: 1, fill: '#dbeafe', stroke: '#2563eb', formula: 'Q = dec·W_q, K/V = enc·W_k/v' });
  y += 58;

  // Decoder path
  drawMatrixBlock(s1 as Sel, cx - 160, y, { width: 70, height: 50, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s1 as Sel, cx - 160, y + 65, 70, 22, 'Q', '#dbeafe', '#2563eb');

  // Encoder path
  drawMatrixBlock(s1 as Sel, cx - 35, y, { width: 55, height: 50, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dcfce7', stroke: '#16a34a' });
  drawTensor(s1 as Sel, cx - 35, y + 65, 55, 22, 'K', '#dcfce7', '#16a34a');
  drawMatrixBlock(s1 as Sel, cx + 35, y, { width: 55, height: 50, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dcfce7', stroke: '#16a34a' });
  drawTensor(s1 as Sel, cx + 35, y + 65, 55, 22, 'V', '#dcfce7', '#16a34a');

  arrowDown(s1 as Sel, cx - 125, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx - 7, y - 22, y - 2, '#16a34a');
  arrowDown(s1 as Sel, cx + 62, y - 22, y - 2, '#16a34a');
  y += 105;

  // Step 2: Split heads
  const s2 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 140, y, 280, 42, 'Step 2 — Split into Heads', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `[batch, n_heads, seq, d_head]` });
  y += 58;
  y += drawHeadSplit(s2, cx, y, nHeads, dHead);

  // Step 3: Full attention (no causal mask)
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Full Attention (No Causal Mask)', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(QK^T / √d) · V' });
  y += 58;

  drawAttentionHeatmap(s3, cx - 80, y, seqLen, 'none');
  y += 190;

  // Step 4: Output
  const s4 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 130, y, 260, 42, 'Step 4 — Output Projection', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s4 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s4 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const totalParams = dModel * dModel * 4;
  lbl(g, cx, y, `Params: ${fmtNum(totalParams)}`, { size: 10, color: '#2563eb', weight: '600' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q from Decoder, K/V from Encoder', shortLabel: 'Separate Sources',
      formula: 'Q = decoder · W_q, K/V = encoder · W_k/v',
      explanation: 'Cross-attention uses queries from the decoder target sequence and keys/values from the encoder source sequence. This allows the decoder to attend to encoder outputs.',
      code: { title: 'Cross QKV', lines: ['q = decoder_hidden @ Wq', 'k = encoder_output @ Wk', 'v = encoder_output @ Wv'] },
      svgGroup: 'step-attn-cross', color: '#2563eb', fill: '#dbeafe' },
    { id: 2, label: 'Split into Heads', shortLabel: 'Head Split',
      formula: '[batch, n_heads, seq, d_head]',
      explanation: 'Split Q/K/V into heads. Q has query sequence length; K/V have encoder sequence length.',
      code: { title: 'Split', lines: ['q = q.view(b, q_len, h, d).transpose(1, 2)', 'k = k.view(b, kv_len, h, d).transpose(1, 2)', 'v = v.view(b, kv_len, h, d).transpose(1, 2)'] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Full Attention', shortLabel: 'Full Attention',
      formula: 'softmax(QK^T / √d_head) · V',
      explanation: 'Each decoder position attends to all encoder positions. No causal mask since decoder is attending to a complete source sequence.',
      code: { title: 'Full Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'attn = softmax(scores, dim=-1)  # no mask', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Bidirectional ─────────────────────────────────────────────────────────────

function renderBidirectional(g: Gsel, seqLen: number, dModel: number, _nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'Bidirectional Attention (BERT/Encoder)', `d_model=${dModel}  seq_len=${seqLen}`);

  // Input
  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 120, y, { width: 80, height: 50, label: 'W_q/k/v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  y += 70;

  // Step 2: Full attention matrix
  const s2 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Full Attention Matrix (No Mask)', { step: 2, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(QK^T / √d)' });
  y += 58;

  drawAttentionHeatmap(s2, cx - 80, y, seqLen, 'none');
  y += 190;

  // Step 3: Weighted sum and output
  const s3 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 140, y, 280, 42, 'Step 3 — Weighted Sum + Output', { step: 3, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = A @ V · W_o' });
  y += 58;
  drawSmallMatrix(s3, cx - 100, y, 5, 5, 12, 'A', '#f3e8ff');
  lbl(s3 as Sel, cx - 30, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, cx - 10, y, 5, 4, 12, 'V', '#dbeafe');
  arrowH(s3 as Sel, 45, 90, y + 24, '#ea580c');
  drawMatrixBlock(s3 as Sel, cx + 60, y, { width: 60, height: 45, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s3 as Sel, cx + 150, y + 8, 100, 26, `out`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: 'Standard projections from a single input sequence.',
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Full Attention (No Mask)', shortLabel: 'Full Attention',
      formula: 'A = softmax(QK^T / √d)',
      explanation: 'Each position attends to all positions. No causal mask — used in encoder-only models like BERT for masked language modeling.',
      code: { title: 'Bidirectional', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'attn = softmax(scores, dim=-1)  # no mask', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 3, label: 'Weighted Sum + Output', shortLabel: 'Output',
      formula: 'out = A @ V · W_o',
      explanation: 'Aggregate values by attention weights, then project.',
      code: { title: 'Output', lines: ['return self.Wo(attn @ v)'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Sliding Window ────────────────────────────────────────────────────────────

function renderSlidingWindow(g: Gsel, seqLen: number, dModel: number, _nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const windowSize = Math.min(128, Math.floor(seqLen / 4));
  const displayWindow = Math.floor(windowSize / (seqLen / 12));
  let y = 28;

  y = drawHeader(g, cx, y, 'Sliding Window Attention (Mistral)', `d_model=${dModel}  window_size=${windowSize}  seq_len=${seqLen}`);

  // Input
  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_q/k/v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  y += 70;

  // Step 2: Window mask
  const s2 = g.append('g').attr('class', 'step-node step-attn-window').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Sliding Window Mask', { step: 2, fill: '#fef3c7', stroke: '#d97706', formula: `attend to [i-${windowSize}, i]` });
  y += 58;

  drawMaskPattern(s2, cx - 70, y, seqLen, 'sliding', displayWindow);
  y += 170;

  // Step 3: Attention within window
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Attention within Window', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(mask(QK^T / √d)) · V' });
  y += 58;

  drawAttentionHeatmap(s3, cx - 80, y, seqLen, 'sliding', displayWindow);
  y += 190;

  // Step 4: Output
  const s4 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 130, y, 260, 42, 'Step 4 — Output Projection', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s4 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s4 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  lbl(g, cx, y, `Complexity: O(seq × window) = O(${seqLen} × ${windowSize}) instead of O(seq²)`, { size: 10, color: '#16a34a', weight: '600' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: 'Standard projections.',
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Sliding Window Mask', shortLabel: 'Window Mask',
      formula: `attend to [i-${windowSize}, i]`,
      explanation: `Each position attends only to the ${windowSize} previous tokens. This reduces complexity from O(seq²) to O(seq × window).`,
      code: { title: 'Window Mask', lines: [`window_size = ${windowSize}`, 'mask = (position - query_pos).abs() <= window_size', 'scores.masked_fill_(~mask, -inf)'] },
      svgGroup: 'step-attn-window', color: '#d97706', fill: '#fef3c7' },
    { id: 3, label: 'Attention within Window', shortLabel: 'Attention',
      formula: 'A = softmax(mask(QK^T / √d)) · V',
      explanation: 'Compute attention only over allowed window positions.',
      code: { title: 'Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'scores = scores.masked_fill(~window_mask, -inf)', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Sparse ────────────────────────────────────────────────────────────────────

function renderSparse(g: Gsel, seqLen: number, dModel: number, _nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'Sparse Attention (BigBird/Longformer)', `d_model=${dModel}  seq_len=${seqLen}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_q/k/v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  y += 70;

  const s2 = g.append('g').attr('class', 'step-node step-attn-sparse').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Build Sparse Pattern', { step: 2, fill: '#fef3c7', stroke: '#d97706', formula: 'local + global + random' });
  y += 58;

  // Three sub-patterns
  drawMaskPattern(s2, cx - 230, y, seqLen, 'sliding', 2);
  lbl(s2 as Sel, cx - 185, y + 160, 'Local', { size: 8, color: '#666' });

  const globalGroup = s2.append('g');
  for (let r = 0; r < 12; r++) {
    for (let c = 0; c < 12; c++) {
      const allowed = c < 2 || r < 2;
      globalGroup.append('rect')
        .attr('x', cx - 70 + c * 10)
        .attr('y', y + r * 10)
        .attr('width', 10).attr('height', 10)
        .attr('fill', allowed ? '#22c55e' : '#fee2e2')
        .attr('stroke', '#e0e0e0').attr('stroke-width', 0.3);
    }
  }
  lbl(globalGroup as Sel, cx - 10, y + 130, 'Global', { size: 8, color: '#666' });

  drawMaskPattern(s2, cx + 90, y, seqLen, 'sparse');
  lbl(s2 as Sel, cx + 150, y + 160, 'Combined', { size: 8, color: '#666' });
  y += 180;

  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Sparse Attention', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(sparse(QK^T) / √d) · V' });
  y += 58;
  drawAttentionHeatmap(s3, cx - 80, y, seqLen, 'sparse');
  y += 190;

  const s4 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 130, y, 260, 42, 'Step 4 — Output Projection', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s4 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s4 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: 'Standard projections.',
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Build Sparse Pattern', shortLabel: 'Sparse Pattern',
      formula: 'local + global + random',
      explanation: 'Sparse attention combines local windowed attention, global tokens that attend to all positions, and random long-range connections.',
      code: { title: 'Sparse Pattern', lines: ['local_mask = (i - j).abs() <= window', 'global_mask = i < n_global or j < n_global', 'random_mask = random_pairs', 'mask = local | global | random'] },
      svgGroup: 'step-attn-sparse', color: '#d97706', fill: '#fef3c7' },
    { id: 3, label: 'Sparse Attention', shortLabel: 'Sparse Attention',
      formula: 'A = softmax(sparse(QK^T) / √d) · V',
      explanation: 'Compute attention only over allowed sparse positions.',
      code: { title: 'Sparse Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'scores = scores.masked_fill(~sparse_mask, -inf)', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Ring Attention ────────────────────────────────────────────────────────────

function renderRing(g: Gsel, seqLen: number, dModel: number, _nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const P = 4;
  const localSeq = Math.floor(seqLen / P);
  let y = 28;

  y = drawHeader(g, cx, y, 'Ring Attention (Distributed)', `d_model=${dModel}  P=${P} ranks  local_seq=${localSeq}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: Sequence split
  const s1 = g.append('g').attr('class', 'step-node step-attn-ring').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Split Sequence across Ranks', { step: 1, fill: '#dbeafe', stroke: '#2563eb', formula: `seq_len / ${P} = ${localSeq}` });
  y += 58;

  for (let rank = 0; rank < P; rank++) {
    const rx = cx - (P * 90) / 2 + rank * 90 + 45;
    drawTensor(s1 as Sel, rx - 35, y, 70, 28, `rank ${rank}`, '#dbeafe', '#2563eb');
    lbl(s1 as Sel, rx, y + 42, `${rank * localSeq}:${(rank + 1) * localSeq}`, { size: 7, color: '#666' });
  }
  y += 60;

  // Step 2: Local QKV
  const s2 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Local Q/K/V Projection per Rank', { step: 2, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q/K/V = local_x · W_q/k/v' });
  y += 58;

  for (let rank = 0; rank < P; rank++) {
    const rx = cx - (P * 80) / 2 + rank * 80 + 40;
    drawMatrixBlock(s2 as Sel, rx - 20, y, { width: 40, height: 40, label: 'W', sublabel: '', fill: '#dbeafe', stroke: '#2563eb' });
  }
  y += 60;

  // Step 3: Ring pass
  const s3 = g.append('g').attr('class', 'step-node step-attn-ring').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Ring-Pass K/V Blocks', { step: 3, fill: '#fef3c7', stroke: '#d97706', formula: 'P2P rotate K/V, accumulate partial outputs' });
  y += 58;

  for (let rank = 0; rank < P; rank++) {
    const rx = cx - (P * 80) / 2 + rank * 80 + 40;
    drawTensor(s3 as Sel, rx - 20, y, 40, 24, `KV${rank}`, '#fef3c7', '#d97706');
    if (rank < P - 1) {
      g.append('line')
        .attr('x1', rx + 25).attr('y1', y + 12)
        .attr('x2', rx + 55).attr('y2', y + 12)
        .attr('stroke', '#d97706').attr('stroke-width', 1.5)
        .attr('marker-end', 'url(#attn-arrow-orange)');
    } else {
      // wrap around arrow (curved)
      g.append('path')
        .attr('d', `M ${rx + 25} ${y + 12} Q ${cx} ${y + 50} ${cx - (P * 80) / 2 + 15} ${y + 12}`)
        .attr('fill', 'none').attr('stroke', '#d97706').attr('stroke-width', 1.5)
        .attr('stroke-dasharray', '4,4');
    }
  }
  lbl(s3 as Sel, cx, y + 50, `${P - 1} rotations until each rank sees all K/V`, { size: 9, color: '#666' });
  y += 75;

  // Step 4: Local attention + accumulate
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 160, y, 320, 42, 'Step 4 — Local Attention + Accumulate', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'O_rank += softmax(Q_local @ K_pass^T / √d) · V_pass' });
  y += 58;

  drawSmallMatrix(s4, cx - 100, y, 4, 5, 12, 'Q_local', '#dbeafe');
  lbl(s4 as Sel, cx - 35, y + 24, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s4, cx - 20, y, 5, 4, 12, 'K_pass^T', '#fef3c7');
  arrowH(s4 as Sel, 40, 90, y + 24, '#9333ea');
  drawSmallMatrix(s4, cx + 70, y, 4, 4, 12, 'O_partial', '#f3e8ff');
  lbl(s4 as Sel, cx + 70, y + 70, '+= accumulate', { size: 8, color: '#9333ea' });
  y += 90;

  // Step 5: Allreduce
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 140, y, 280, 42, 'Step 5 — AllReduce + Output', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'allreduce(O) → Concat → W_o' });
  y += 58;
  drawTensor(s5 as Sel, cx - 50, y, 100, 28, 'allreduce', '#ffedd5', '#ea580c');
  drawTensor(s5 as Sel, cx + 70, y + 5, 100, 26, `out`, '#ffedd5', '#ea580c');
  y += 60;

  const steps: AttnStep[] = [
    { id: 1, label: 'Split Sequence across Ranks', shortLabel: 'Split',
      formula: `seq_len / ${P} = ${localSeq}`,
      explanation: `Sequence is split into ${P} contiguous chunks, each on a different GPU rank.`,
      code: { title: 'Split', lines: [`local_seq_len = seq_len // ${P}`, 'x_local = x[rank * local_seq_len : (rank+1) * local_seq_len]'] },
      svgGroup: 'step-attn-ring', color: '#2563eb', fill: '#dbeafe' },
    { id: 2, label: 'Local Q/K/V Projection', shortLabel: 'Local QKV',
      formula: 'Q/K/V = local_x · W_q/k/v',
      explanation: 'Each rank computes Q/K/V for its local sequence chunk.',
      code: { title: 'Local QKV', lines: ['q_local = x_local @ Wq', 'k_local = x_local @ Wk', 'v_local = x_local @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 3, label: 'Ring-Pass K/V Blocks', shortLabel: 'Ring Pass',
      formula: 'P2P rotate K/V',
      explanation: `K/V blocks rotate through ranks via P2P communication. After ${P - 1} rotations, each rank has seen all K/V blocks.`,
      code: { title: 'Ring Pass', lines: ['for step in range(P - 1):', '  send K/V to next rank', '  recv K/V from prev rank', '  accumulate local attention'] },
      svgGroup: 'step-attn-ring', color: '#d97706', fill: '#fef3c7' },
    { id: 4, label: 'Local Attention + Accumulate', shortLabel: 'Accumulate',
      formula: 'O += softmax(Q_local @ K_pass^T / √d) · V_pass',
      explanation: 'Each rank computes local attention with the current K/V block and accumulates partial outputs.',
      code: { title: 'Accumulate', lines: ['scores = (q_local @ k_pass.T) / sqrt(d_head)', 'attn = softmax(scores)', 'o_local += attn @ v_pass'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'AllReduce + Output', shortLabel: 'Output',
      formula: 'allreduce(O) → W_o',
      explanation: 'Partial outputs are combined across ranks via allreduce, then projected.',
      code: { title: 'Output', lines: ['o = allreduce(o_local)', 'return self.Wo(concat(o))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Flash Attention ───────────────────────────────────────────────────────────

function renderFlash(g: Gsel, seqLen: number, dModel: number, _nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const blockSize = 64;
  let y = 28;

  y = drawHeader(g, cx, y, 'Flash Attention (IO-Aware)', `d_model=${dModel}  block_size=${blockSize}  seq_len=${seqLen}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_q/k/v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  y += 70;

  // Step 2: Tile into SRAM
  const s2 = g.append('g').attr('class', 'step-node step-attn-tile').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Tile into SRAM Blocks', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `B_r × B_c = ${blockSize} × ${blockSize}` });
  y += 58;

  // Q tiles
  lbl(s2 as Sel, cx - 130, y, 'Q tiles', { size: 9, weight: '600', color: '#2563eb' });
  for (let i = 0; i < 4; i++) {
    drawTensor(s2 as Sel, cx - 150 + i * 60, y + 12, 45, 20, `Q_${i}`, '#dbeafe', '#2563eb');
  }
  y += 50;

  // K/V tiles
  lbl(s2 as Sel, cx - 130, y, 'K/V tiles', { size: 9, weight: '600', color: '#16a34a' });
  for (let i = 0; i < 4; i++) {
    drawTensor(s2 as Sel, cx - 150 + i * 60, y + 12, 45, 20, `K/V_${i}`, '#dcfce7', '#16a34a');
  }
  y += 55;

  // Step 3: Block-level QK^T
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Block-Level QK^T + Mask', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'S_ij = Q_i @ K_j^T / √d' });
  y += 58;

  drawSmallMatrix(s3, cx - 100, y, 4, 4, 13, 'Q_i', '#dbeafe');
  lbl(s3 as Sel, cx - 40, y + 26, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, cx - 25, y, 4, 4, 13, 'K_j^T', '#dcfce7');
  arrowH(s3 as Sel, 35, 85, y + 26, '#9333ea');
  drawSmallMatrix(s3, cx + 70, y, 4, 4, 13, 'S_ij', '#f3e8ff');
  y += 80;

  // Step 4: Online softmax
  const s4 = g.append('g').attr('class', 'step-node step-attn-online').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 170, y, 340, 42, 'Step 4 — Online Softmax (Running Max/Sum)', { step: 4, fill: '#fef3c7', stroke: '#d97706', formula: 'm_new, l_new, O_rescaled' });
  y += 58;

  drawTensor(s4 as Sel, cx - 130, y, 90, 28, 'running max', '#fef3c7', '#d97706');
  drawTensor(s4 as Sel, cx - 20, y, 90, 28, 'running sum', '#fef3c7', '#d97706');
  drawTensor(s4 as Sel, cx + 90, y, 90, 28, 'O partial', '#fef3c7', '#d97706');
  y += 50;

  // Step 5: Rescale and accumulate
  const s5 = g.append('g').attr('class', 'step-node step-attn-accum').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 160, y, 320, 42, 'Step 5 — Rescale + Accumulate Outputs', { step: 5, fill: '#f3e8ff', stroke: '#9333ea', formula: 'O_new = rescale(O_old) + P_ij @ V_j' });
  y += 58;

  drawSmallMatrix(s5, cx - 100, y, 4, 4, 13, 'P_ij', '#fef3c7');
  lbl(s5 as Sel, cx - 40, y + 26, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s5, cx - 25, y, 4, 4, 13, 'V_j', '#dcfce7');
  arrowH(s5 as Sel, 35, 85, y + 26, '#9333ea');
  drawSmallMatrix(s5, cx + 70, y, 4, 4, 13, 'O_i', '#f3e8ff');
  y += 80;

  // Step 6: Output
  const s6 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '6');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s6 as Sel, cx - 150, y, 300, 42, 'Step 6 — Final Output Projection', { step: 6, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s6 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s6 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  lbl(g, cx, y, 'Key benefit: no materialization of full [seq, seq] attention matrix in HBM', { size: 10, color: '#16a34a', weight: '600' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: 'Standard projections.',
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Tile into SRAM', shortLabel: 'Tiling',
      formula: `B_r × B_c = ${blockSize} × ${blockSize}`,
      explanation: `Flash Attention tiles Q/K/V into SRAM blocks of size ${blockSize}×${blockSize}. Each block fits in fast on-chip memory, avoiding HBM reads/writes for the full attention matrix.`,
      code: { title: 'Tiling', lines: [`block_size = ${blockSize}`, 'for Q_block in tiled(Q):', '  for K_block, V_block in tiled(K, V):', '    compute in SRAM'] },
      svgGroup: 'step-attn-tile', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Block-Level QK^T', shortLabel: 'Block QK^T',
      formula: 'S_ij = Q_i @ K_j^T / √d',
      explanation: 'Compute attention scores block by block inside SRAM.',
      code: { title: 'Block Scores', lines: ['S_ij = (Q_i @ K_j.T) / sqrt(d_head)', 'S_ij = apply_causal_mask(S_ij)'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Online Softmax', shortLabel: 'Online Softmax',
      formula: 'm_new, l_new',
      explanation: 'Track running maximum and sum for numerical stability. Update with each new block.',
      code: { title: 'Online Softmax', lines: ['m_new = max(m_old, rowmax(S_ij))', 'l_new = exp(m_old-m_new)*l_old + rowsum(exp(S_ij-m_new))'] },
      svgGroup: 'step-attn-online', color: '#d97706', fill: '#fef3c7' },
    { id: 5, label: 'Rescale + Accumulate', shortLabel: 'Accumulate',
      formula: 'O_new = rescale(O_old) + P_ij @ V_j',
      explanation: 'Rescale previous partial output with new running max, then add contribution from current V block.',
      code: { title: 'Accumulate', lines: ['O_old = (l_old / l_new) * exp(m_old - m_new) * O_old', 'O_new = O_old + (1/l_new) * exp(S_ij - m_new) @ V_j'] },
      svgGroup: 'step-attn-accum', color: '#9333ea', fill: '#f3e8ff' },
    { id: 6, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Paged Attention ───────────────────────────────────────────────────────────

function renderPaged(g: Gsel, seqLen: number, dModel: number, _nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const pageSize = 16;
  const nPages = Math.ceil(seqLen / pageSize);
  let y = 28;

  y = drawHeader(g, cx, y, 'PagedAttention (vLLM)', `d_model=${dModel}  page_size=${pageSize}  n_pages=${nPages}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_q/k/v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  y += 70;

  // Step 2: Pack K/V into pages
  const s2 = g.append('g').attr('class', 'step-node step-attn-paged').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Pack K/V into Non-Contiguous Pages', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `page_size=${pageSize}` });
  y += 58;

  for (let p = 0; p < Math.min(nPages, 6); p++) {
    drawTensor(s2 as Sel, cx - 150 + p * 55, y, 45, 22, `P${p}`, '#dbeafe', '#2563eb');
  }
  y += 45;

  // Step 3: Block table
  const s3 = g.append('g').attr('class', 'step-node step-attn-lookup').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Block Table Maps Logical to Physical Pages', { step: 3, fill: '#fef3c7', stroke: '#d97706', formula: 'block_table[logical_pos] = physical_page' });
  y += 58;

  // Block table as array
  const blockTable = [3, 1, 4, 0, 5, 2];
  lbl(s3 as Sel, cx - 150, y, 'logical:', { size: 8, color: '#666' });
  lbl(s3 as Sel, cx - 150, y + 14, 'physical:', { size: 8, color: '#666' });
  for (let i = 0; i < Math.min(nPages, 6); i++) {
    lbl(s3 as Sel, cx - 110 + i * 50, y, `${i}`, { size: 8, color: '#2563eb' });
    drawTensor(s3 as Sel, cx - 130 + i * 50, y + 10, 35, 18, `${blockTable[i]}`, '#fef3c7', '#d97706');
  }
  y += 50;

  // Step 4: Attention via block lookup
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 160, y, 320, 42, 'Step 4 — Attention via Block Table Lookup', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'Q @ K[block_table]^T' });
  y += 58;

  drawSmallMatrix(s4, cx - 80, y, 4, 6, 12, 'Q', '#dbeafe');
  arrowH(s4 as Sel, -5, 60, y + 24, '#9333ea');
  drawSmallMatrix(s4, cx + 50, y, 6, 4, 12, 'K^T\n(block)', '#fef3c7');
  y += 90;

  // Step 5: Output
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: 'Standard projections.',
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Pack K/V into Pages', shortLabel: 'Pack Pages',
      formula: `page_size=${pageSize}`,
      explanation: `KV cache is packed into fixed-size pages of ${pageSize} tokens. Pages can be allocated non-contiguously.`,
      code: { title: 'Pack', lines: [`pages = k.view(-1, ${pageSize}, n_heads, d_head)`] },
      svgGroup: 'step-attn-paged', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Block Table', shortLabel: 'Block Table',
      formula: 'block_table[logical_pos] = physical_page',
      explanation: 'A block table maps logical token positions to physical page indices, similar to virtual memory.',
      code: { title: 'Block Table', lines: ['block_table = allocate_pages(seq_len)', 'page_idx = block_table[token_pos // page_size]'] },
      svgGroup: 'step-attn-lookup', color: '#d97706', fill: '#fef3c7' },
    { id: 4, label: 'Attention via Block Lookup', shortLabel: 'Block Lookup',
      formula: 'Q @ K[block_table]^T',
      explanation: 'Retrieve K/V via block table during attention. This enables efficient memory sharing and copy-on-write for beam search.',
      code: { title: 'Lookup', lines: ['for token in sequence:', '  page = block_table[token_pos]', '  k, v = physical_kv_cache[page]', '  compute attention'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Linear Attention ──────────────────────────────────────────────────────────

function renderLinear(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'Linear Attention', `d_model=${dModel}  seq_len=${seqLen}  d_head=${dHead}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection + head split
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 160, y, 320, 42, 'Step 1 — Q/K/V Projection + Head Split', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q, K, V = xW_q/k/v, reshape to heads' });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_q/k/v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  y += 70;

  // Step 2: Feature maps
  const s2 = g.append('g').attr('class', 'step-node step-attn-phi').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 150, y, 300, 42, 'Step 2 — Apply Feature Maps φ(Q), φ(K)', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: 'φ(x) = elu(x) + 1' });
  y += 58;

  drawSmallMatrix(s2, cx - 120, y, 5, 4, 12, 'Q', '#dbeafe');
  arrowH(s2 as Sel, -60, 10, y + 24, '#2563eb');
  drawSmallMatrix(s2, cx - 5, y, 5, 4, 12, 'φ(Q)', '#dbeafe');
  y += 70;

  // Step 3: Matrix multiplication reorder
  const s3 = g.append('g').attr('class', 'step-node step-attn-linear').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 170, y, 340, 42, 'Step 3 — Reorder Multiplication for Linear Complexity', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'φ(Q) @ (φ(K)^T @ V)' });
  y += 58;

  lbl(s3 as Sel, cx - 160, y, 'Standard:', { size: 9, weight: '600', color: '#666' });
  lbl(s3 as Sel, cx - 60, y, '(Q @ K^T) @ V  →  O(seq²)', { size: 9, font: 'monospace', color: '#666' });
  y += 20;
  lbl(s3 as Sel, cx - 160, y, 'Linear:', { size: 9, weight: '600', color: '#16a34a' });
  lbl(s3 as Sel, cx - 60, y, 'φ(Q) @ (φ(K)^T @ V)  →  O(seq)', { size: 9, font: 'monospace', color: '#16a34a' });
  y += 30;

  drawSmallMatrix(s3, cx - 130, y, 4, 4, 12, 'φ(K)^T', '#dbeafe');
  lbl(s3 as Sel, cx - 70, y + 24, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, cx - 55, y, 4, 3, 12, 'V', '#dcfce7');
  arrowH(s3 as Sel, 5, 60, y + 20, '#9333ea');
  drawSmallMatrix(s3, cx + 50, y, 4, 3, 12, 'KV', '#f3e8ff');
  lbl(s3 as Sel, cx + 50, y + 55, '[d, d]', { size: 8, color: '#9333ea' });
  y += 70;

  // Step 4: Multiply by Q
  const s4 = g.append('g').attr('class', 'step-node step-attn-weighted').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 140, y, 280, 42, 'Step 4 — Multiply by φ(Q)', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = φ(Q) @ KV' });
  y += 58;

  drawSmallMatrix(s4, cx - 100, y, 5, 4, 12, 'φ(Q)', '#dbeafe');
  lbl(s4 as Sel, cx - 40, y + 24, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s4, cx - 25, y, 4, 3, 12, 'KV', '#f3e8ff');
  arrowH(s4 as Sel, 35, 80, y + 20, '#ea580c');
  drawSmallMatrix(s4, cx + 70, y, 5, 3, 12, 'out', '#ffedd5');
  y += 70;

  // Step 5: Output
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection + Head Split', shortLabel: 'QKV',
      formula: 'Q, K, V = xW_q/k/v',
      explanation: 'Standard projections and head split.',
      code: { title: 'QKV', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv', 'q, k, v = split_heads(q, k, v)'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Feature Maps', shortLabel: 'Feature Maps',
      formula: 'φ(Q), φ(K)',
      explanation: 'Apply positive feature maps to queries and keys so attention matrix becomes decomposable.',
      code: { title: 'Feature Maps', lines: ['phi = lambda x: F.elu(x) + 1', 'q = phi(q)', 'k = phi(k)'] },
      svgGroup: 'step-attn-phi', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Reorder Multiplication', shortLabel: 'Linear',
      formula: 'φ(Q) @ (φ(K)^T @ V)',
      explanation: 'Compute (φ(K)^T @ V) first: [d, seq] @ [seq, d] = [d, d]. This is independent of query position and reusable.',
      code: { title: 'Linear', lines: ['KV = k.T @ v  # [d, d]', '# Complexity: O(seq * d^2)'] },
      svgGroup: 'step-attn-linear', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Multiply by φ(Q)', shortLabel: 'Q @ KV',
      formula: 'out = φ(Q) @ KV',
      explanation: 'For each query position, multiply by the precomputed KV matrix. Total complexity O(seq × d²).',
      code: { title: 'Output', lines: ['out = q @ KV  # [seq, d]'] },
      svgGroup: 'step-attn-weighted', color: '#ea580c', fill: '#ffedd5' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── MLA ───────────────────────────────────────────────────────────────────────

function renderMLA(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const latentDim = Math.floor(dModel / 4);
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'MLA (DeepSeek Latent Attention)', `d_model=${dModel}  latent_dim=${latentDim}  n_heads=${nHeads}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: Q projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q Projection (full dim)', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: `Q = x · W_q  [${dModel}→${dModel}]` });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s1 as Sel, cx + 60, y + 10, 80, 26, `Q`, '#dbeafe', '#2563eb');
  y += 80;

  // Step 2: Compress K/V to latent
  const s2 = g.append('g').attr('class', 'step-node step-attn-compress').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 170, y, 340, 42, 'Step 2 — Compress K/V into Latent Vector', { step: 2, fill: '#f3e8ff', stroke: '#9333ea', formula: `c = x · W_down  [${dModel}→${latentDim}]` });
  y += 58;

  drawMatrixBlock(s2 as Sel, cx - 50, y, { width: 60, height: 60, label: 'W_down', sublabel: `[${dModel}, ${latentDim}]`, fill: '#f3e8ff', stroke: '#9333ea' });
  arrowH(s2 as Sel, 20, 90, y + 30, '#9333ea');
  drawTensor(s2 as Sel, cx + 70, y + 15, 90, 28, `c [b, ${seqLen}, ${latentDim}]`, '#f3e8ff', '#9333ea');
  lbl(s2 as Sel, cx + 170, y + 30, '4× smaller', { size: 9, color: '#9333ea', weight: '600' });
  y += 90;

  // Step 3: Decompress to K/V
  const s3 = g.append('g').attr('class', 'step-node step-attn-decompress').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 170, y, 340, 42, 'Step 3 — Decompress Latent to K/V', { step: 3, fill: '#dbeafe', stroke: '#2563eb', formula: `K/V = c · W_up  [${latentDim}→${dModel}]` });
  y += 58;

  drawTensor(s3 as Sel, cx - 120, y + 15, 80, 26, 'c', '#f3e8ff', '#9333ea');
  arrowH(s3 as Sel, -35, 25, y + 28, '#2563eb');
  drawMatrixBlock(s3 as Sel, cx + 35, y, { width: 50, height: 60, label: 'W_up', sublabel: `[${latentDim}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  arrowH(s3 as Sel, 90, 170, y + 30, '#2563eb');
  drawTensor(s3 as Sel, cx + 110, y + 10, 70, 26, 'K', '#dbeafe', '#2563eb');
  drawTensor(s3 as Sel, cx + 110, y + 45, 70, 26, 'V', '#dbeafe', '#2563eb');
  y += 100;

  // Step 4: Split heads
  const s4 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 140, y, 280, 42, 'Step 4 — Split into Heads', { step: 4, fill: '#dbeafe', stroke: '#2563eb', formula: `[batch, n_heads, seq, d_head]` });
  y += 58;
  y += drawHeadSplit(s4, cx, y, nHeads, dHead);

  // Step 5: Attention + output
  const s5 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 150, y, 300, 42, 'Step 5 — Attention + Output', { step: 5, fill: '#f3e8ff', stroke: '#9333ea', formula: 'softmax(QK^T / √d) · V' });
  y += 58;

  drawAttentionHeatmap(s5, cx - 80, y, seqLen, 'causal');
  y += 190;

  const s6 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '6');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s6 as Sel, cx - 130, y, 260, 42, 'Step 6 — Output Projection', { step: 6, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s6 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s6 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q Projection (full dim)', shortLabel: 'Q Projection',
      formula: `Q = x · W_q  [${dModel}→${dModel}]`,
      explanation: 'Q is projected normally to full d_model dimension.',
      code: { title: 'Q', lines: [`Wq: [${dModel}, ${dModel}]`, 'q = x @ Wq'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Compress K/V to Latent', shortLabel: 'Compress',
      formula: `c = x · W_down  [${dModel}→${latentDim}]`,
      explanation: `K and V are compressed into a shared latent vector of dimension ${latentDim}. This reduces KV cache size by ~4×.`,
      code: { title: 'Compress', lines: [`W_down: [${dModel}, ${latentDim}]`, `c = x @ W_down  # [batch, seq, ${latentDim}]`] },
      svgGroup: 'step-attn-compress', color: '#9333ea', fill: '#f3e8ff' },
    { id: 3, label: 'Decompress to K/V', shortLabel: 'Decompress',
      formula: `K/V = c · W_up  [${latentDim}→${dModel}]`,
      explanation: 'The latent vector is up-projected back to full dimension for K and V.',
      code: { title: 'Decompress', lines: [`W_up_k: [${latentDim}, ${dModel}]`, `W_up_v: [${latentDim}, ${dModel}]`, 'k = c @ W_up_k', 'v = c @ W_up_v'] },
      svgGroup: 'step-attn-decompress', color: '#2563eb', fill: '#dbeafe' },
    { id: 4, label: 'Split into Heads', shortLabel: 'Head Split',
      formula: '[batch, n_heads, seq, d_head]',
      explanation: 'Split Q/K/V into heads.',
      code: { title: 'Split', lines: ['q, k, v = split_heads(q, k, v)'] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 5, label: 'Attention', shortLabel: 'Attention',
      formula: 'softmax(QK^T / √d) · V',
      explanation: 'Standard scaled dot-product attention.',
      code: { title: 'Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 6, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── RoPE + ALiBi ──────────────────────────────────────────────────────────────

function renderRoPEALiBi(g: Gsel, _seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'RoPE + ALiBi (Combined)', `d_model=${dModel}  n_heads=${nHeads}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${nHeads}, seq, d_head]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_q/k/v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  y += 70;

  // Step 2: RoPE rotation
  const s2 = g.append('g').attr('class', 'step-node step-attn-rope').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 140, y, 280, 42, 'Step 2 — RoPE Rotate Q/K', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: 'R(θ·pos) · [q, k]' });
  y += 58;

  // 2D rotation illustration
  const planeR = 40;
  const planeCy = y + planeR + 8;
  s2.append('circle').attr('cx', cx).attr('cy', planeCy).attr('r', planeR)
    .attr('fill', 'none').attr('stroke', '#ddd').attr('stroke-width', 1);
  s2.append('line').attr('x1', cx - planeR).attr('y1', planeCy).attr('x2', cx + planeR).attr('y2', planeCy).attr('stroke', '#ddd').attr('stroke-width', 0.5);
  s2.append('line').attr('x1', cx).attr('y1', planeCy - planeR).attr('x2', cx).attr('y2', planeCy + planeR).attr('stroke', '#ddd').attr('stroke-width', 0.5);

  // original vector
  s2.append('line').attr('x1', cx).attr('y1', planeCy).attr('x2', cx + planeR * 0.7).attr('y2', planeCy - planeR * 0.3).attr('stroke', '#2563eb').attr('stroke-width', 2);
  // rotated vector
  const angle = 0.8;
  s2.append('line').attr('x1', cx).attr('y1', planeCy).attr('x2', cx + planeR * 0.7 * Math.cos(angle)).attr('y2', planeCy - planeR * 0.7 * Math.sin(angle)).attr('stroke', '#ea580c').attr('stroke-width', 2);
  // arc
  const arcGen = d3.arc().innerRadius(planeR * 0.3).outerRadius(planeR * 0.35);
  s2.append('path')
    .attr('d', arcGen({ innerRadius: planeR * 0.3, outerRadius: planeR * 0.35, startAngle: -0.4, endAngle: 0.4 }) as string)
    .attr('transform', `translate(${cx}, ${planeCy})`)
    .attr('fill', '#ea580c');

  lbl(s2 as Sel, cx, y + planeR * 2 + 20, 'Rotate Q/K vector pairs by θ_i × position', { size: 9, color: '#666' });
  y += planeR * 2 + 45;

  // Step 3: ALiBi bias
  const s3 = g.append('g').attr('class', 'step-node step-attn-alibi').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Add ALiBi Slope Bias', { step: 3, fill: '#dcfce7', stroke: '#16a34a', formula: 'scores += m · |i - j|' });
  y += 58;

  // Slope bars
  const slopes = [0.5, 0.25, 0.125, 0.0625];
  for (let h = 0; h < 4; h++) {
    const sx = cx - 120 + h * 80;
    const barH = 30 * slopes[h];
    s3.append('rect').attr('x', sx).attr('y', y + 30 - barH).attr('width', 20).attr('height', barH).attr('fill', '#16a34a');
    lbl(s3 as Sel, sx + 10, y + 45, `h${h}`, { size: 7, color: '#666' });
    lbl(s3 as Sel, sx + 10, y + 56, `${slopes[h]}`, { size: 6, color: '#666' });
  }
  lbl(s3 as Sel, cx, y + 75, 'Each head has a different slope; bias grows with distance', { size: 9, color: '#666' });
  y += 90;

  // Step 4: Attention
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 170, y, 340, 42, 'Step 4 — Attention with RoPE + ALiBi', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax((Q_rot K_rot^T + bias) / √d) · V' });
  y += 58;

  drawSmallMatrix(s4, cx - 120, y, 5, 5, 12, 'Q_rot @ K_rot^T', '#dbeafe');
  lbl(s4 as Sel, cx - 40, y + 30, '+', { size: 14, weight: '700', color: '#666' });
  drawSmallMatrix(s4, cx - 20, y, 5, 5, 12, 'bias', '#dcfce7');
  arrowH(s4 as Sel, 40, 90, y + 30, '#9333ea');
  drawSmallMatrix(s4, cx + 80, y, 5, 5, 12, 'A', '#f3e8ff');
  y += 90;

  // Step 5: Output
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 120, 28, `out [b, seq, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: 'Standard projections.',
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'RoPE Rotate Q/K', shortLabel: 'RoPE',
      formula: 'R(θ·pos) · [q, k]',
      explanation: 'RoPE rotates Q/K vector pairs in 2D planes by angle θ_i × position. Dot product of rotated Q/K encodes relative position (m-n).',
      code: { title: 'RoPE', lines: ['q_rot = rotate(q, theta * pos)', 'k_rot = rotate(k, theta * pos)'] },
      svgGroup: 'step-attn-rope', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'ALiBi Slope Bias', shortLabel: 'ALiBi',
      formula: 'scores += m · |i - j|',
      explanation: 'ALiBi adds a linear bias based on distance: score[i,j] += m × |i-j| where m is a head-specific slope.',
      code: { title: 'ALiBi', lines: ['slope = head_specific_slope', 'bias = slope * abs(i - j)', 'scores += bias'] },
      svgGroup: 'step-attn-alibi', color: '#16a34a', fill: '#dcfce7' },
    { id: 4, label: 'Attention', shortLabel: 'Attention',
      formula: 'A = softmax((Q_rot K_rot^T + bias) / √d) · V',
      explanation: 'Attention with both RoPE rotation and ALiBi bias.',
      code: { title: 'Combined', lines: ['scores = (q_rot @ k_rot.T) / sqrt(d_head)', 'scores += alibi_bias', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: 'Standard output projection.',
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Arrow marker definitions ──────────────────────────────────────────────────

function addArrowMarkerDef(g: Gsel, id: string, color: string): void {
  const defs = g.selectAll('defs').empty() ? g.append('defs') : g.select('defs');
  defs.append('marker')
    .attr('id', id)
    .attr('viewBox', '0 -5 10 10')
    .attr('refX', 8)
    .attr('refY', 0)
    .attr('markerWidth', 6)
    .attr('markerHeight', 6)
    .attr('orient', 'auto')
    .append('path')
    .attr('d', 'M0,-5L10,0L0,5')
    .attr('fill', color);
}

// ── Main Entry ────────────────────────────────────────────────────────────────

export function renderAttentionDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph,
): { width: number; height: number; steps: AttnStep[] } {
  const variant = String(params.variant ?? 'standard');
  const seqLen = Number(params.seq_len ?? 128);
  const dModel = Number(params.d_model ?? 512);
  const nHeads = Number(params.n_heads ?? 8);
  const W = 800;

  addArrowMarkerDef(g as Gsel, 'attn-arrow-orange', '#d97706');

  switch (variant) {
    case 'gqa':
      return renderGQAMQA(g as Gsel, seqLen, dModel, nHeads, W, false);
    case 'mqa':
      return renderGQAMQA(g as Gsel, seqLen, dModel, nHeads, W, true);
    case 'cross-attention':
      return renderCrossAttention(g as Gsel, seqLen, dModel, nHeads, W);
    case 'bidirectional':
      return renderBidirectional(g as Gsel, seqLen, dModel, nHeads, W);
    case 'sliding-window':
      return renderSlidingWindow(g as Gsel, seqLen, dModel, nHeads, W);
    case 'sparse':
      return renderSparse(g as Gsel, seqLen, dModel, nHeads, W);
    case 'ring':
      return renderRing(g as Gsel, seqLen, dModel, nHeads, W);
    case 'flash':
      return renderFlash(g as Gsel, seqLen, dModel, nHeads, W);
    case 'paged':
      return renderPaged(g as Gsel, seqLen, dModel, nHeads, W);
    case 'linear-attention':
      return renderLinear(g as Gsel, seqLen, dModel, nHeads, W);
    case 'mla':
      return renderMLA(g as Gsel, seqLen, dModel, nHeads, W);
    case 'rope_alibi':
      return renderRoPEALiBi(g as Gsel, seqLen, dModel, nHeads, W);
    default:
      return renderStandard(g as Gsel, seqLen, dModel, nHeads, W);
  }
}